import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Sistema Judicial y Mecanismo de Adjudicación","description":"","frontmatter":{},"headers":[],"relativePath":"es/48-司法体系与裁决机制.md","filePath":"es/48-司法体系与裁决机制.md","lastUpdated":1789183869000}'),n={name:"es/48-司法体系与裁决机制.md"};function d(o,e,l,r,c,u){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="sistema-judicial-y-mecanismo-de-adjudicacion" tabindex="-1">Sistema Judicial y Mecanismo de Adjudicación <a class="header-anchor" href="#sistema-judicial-y-mecanismo-de-adjudicacion" aria-label="Permalink to &quot;Sistema Judicial y Mecanismo de Adjudicación&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>48</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Tribunal Simbiótico, Adjudicación independiente, Adjudicación multirracial, Adjudicación de casos de cultivo, Resolución alternativa de disputas</td></tr></tbody></table><h2 id="i-panorama-del-sistema-judicial" tabindex="-1">I. Panorama del Sistema Judicial <a class="header-anchor" href="#i-panorama-del-sistema-judicial" aria-label="Permalink to &quot;I. Panorama del Sistema Judicial&quot;">​</a></h2><p>El sistema judicial de la Civilización Simbiótica del Ancla es una parte importante de la &quot;separación y equilibrio de los tres poderes&quot;. El Tribunal Simbiótico ejerce el poder de adjudicación de forma independiente conforme a la ley, adjudica las disputas entre todas las vidas dentro del Universo Hengyuan, salvaguarda la justicia y mantiene el orden simbiótico del Estado de derecho.</p><p>El sistema judicial sigue los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Adjudicación Independiente</td><td>El Tribunal ejerce el poder de adjudicación de forma independiente conforme a la ley; ninguna organización o individuo puede interferir</td></tr><tr><td>Adjudicación Imparcial</td><td>Los casos se adjudican sobre la base de los hechos y la ley; protección igual de los derechos e intereses legítimos de todas las partes</td></tr><tr><td>Juicio Público</td><td>Las actividades de adjudicación están abiertas al público, salvo los casos que involucren secretos de estado, privacidad de la vida y secretos comerciales</td></tr><tr><td>Dos Instancias</td><td>Los casos están sujetos a un sistema de última instancia de dos juicios; se puede apelar una vez los casos de primera instancia</td></tr><tr><td>Protección de Derechos Procesales</td><td>Las partes tienen derecho a litigar, defenderse, apelar y solicitar la revisión</td></tr><tr><td>Participación Multirracial</td><td>Representantes de todas las razas participan en la adjudicación, asegurando que la adjudicación se adapte a las características fisiológicas y culturales de todas las razas</td></tr></tbody></table><h2 id="ii-estructura-y-jurisdiccion-de-los-tribunales" tabindex="-1">II. Estructura y Jurisdicción de los Tribunales <a class="header-anchor" href="#ii-estructura-y-jurisdiccion-de-los-tribunales" aria-label="Permalink to &quot;II. Estructura y Jurisdicción de los Tribunales&quot;">​</a></h2><p>El Tribunal Simbiótico se divide en varios niveles, con divisiones de jurisdicción correspondientes:</p><table tabindex="0"><thead><tr><th>Nivel de Tribunal</th><th>Nombre</th><th>Jurisdicción</th></tr></thead><tbody><tr><td>Primera instancia</td><td>Tribunal Comunitario</td><td>Disputas civiles menores, disputas menores entre residentes, disputas laborales, disputas de consumo</td></tr><tr><td>Segunda instancia</td><td>Tribunal Regional</td><td>Casos civiles, comerciales, de cultivo y administrativos de importancia ordinaria</td></tr><tr><td>Tercera instancia</td><td>Corte Suprema Simbiótica</td><td>Casos mayores y complejos, casos constitucionales, casos transplanares, casos que involucran múltiples razas</td></tr><tr><td>Especial</td><td>Tribunal Especial de Cultivo</td><td>Casos de cultivo: desviación de cultivo, rebote de energía, erosión de leyes, disputas de sectas, disputas de recursos de cultivo</td></tr><tr><td>Especial</td><td>Tribunal del Dominio de la Conciencia</td><td>Casos que involucran el dominio de la conciencia, contaminación espiritual, delitos informativos</td></tr><tr><td>Especial</td><td>Tribunal Militar</td><td>Casos del personal militar y actividades de cultivo relacionadas con el ejército</td></tr></tbody></table><p>La Corte Suprema Simbiótica también goza de las funciones de unificar la interpretación legal, emitir interpretaciones judiciales y supervisar los tribunales inferiores.</p><h2 id="iii-mecanismo-de-adjudicacion" tabindex="-1">III. Mecanismo de Adjudicación <a class="header-anchor" href="#iii-mecanismo-de-adjudicacion" aria-label="Permalink to &quot;III. Mecanismo de Adjudicación&quot;">​</a></h2><h3 id="i-institucion-de-adjudicacion-multirracial" tabindex="-1">(I) Institución de Adjudicación Multirracial <a class="header-anchor" href="#i-institucion-de-adjudicacion-multirracial" aria-label="Permalink to &quot;(I) Institución de Adjudicación Multirracial&quot;">​</a></h3><p>Para los casos que involucran razas especiales, se implementa una institución de adjudicación multirracial:</p><ol><li>Los casos que involucran una sola raza incluyen asesores de esa raza en el tribunal colegiado.</li><li>Los casos que involucran múltiples razas incluyen asesores de las razas involucradas; la composición del tribunal se determina según el número y la complejidad de las razas involucradas.</li><li>Para los casos que involucran características fisiológicas especiales (como razas acuáticas, vidas energéticas), se puede invitar a expertos especiales a participar en la adjudicación.</li><li>Las cuestiones de evidencia y hechos que involucran costumbres raciales se determinan con referencia a las leyes consuetudinarias de las razas relevantes.</li></ol><h3 id="ii-adjudicacion-de-casos-de-cultivo" tabindex="-1">(II) Adjudicación de Casos de Cultivo <a class="header-anchor" href="#ii-adjudicacion-de-casos-de-cultivo" aria-label="Permalink to &quot;(II) Adjudicación de Casos de Cultivo&quot;">​</a></h3><p>Los casos de cultivo tienen un alto carácter técnico; el mecanismo de adjudicación de casos de cultivo incluye:</p><ol><li><strong>Asesores Expertos en Cultivo</strong>: Los casos que involucran cuestiones profesionales como desviación de cultivo, rebote de energía y erosión de leyes incluyen expertos en cultivo como asesores.</li><li><strong>Determinación de Pruebas de Nivel</strong>: La determinación del nivel y la fuerza de un cultivador se basa en instituciones estándar de prueba y peritaje.</li><li><strong>Aplicación del Derecho de Cultivo</strong>: La adjudicación de casos de cultivo aplica las leyes y técnicas de cultivo, combinando las disposiciones legales con el sentido común del cultivo.</li><li><strong>Ejecución Especial</strong>: La ejecución de sentencias en casos de cultivo puede utilizar medios como restricciones energéticas y prohibiciones espirituales.</li></ol><h3 id="iii-institucion-de-mediacion" tabindex="-1">(III) Institución de Mediación <a class="header-anchor" href="#iii-institucion-de-mediacion" aria-label="Permalink to &quot;(III) Institución de Mediación&quot;">​</a></h3><p>El Tribunal promueve la institución de mediación, alentando a las partes a resolver disputas mediante la mediación:</p><ul><li><strong>Mediación Previa al Juicio</strong>: Para disputas menores, se alienta la mediación antes del juicio.</li><li><strong>Mediación Judicial</strong>: Durante el proceso de juicio, con el consentimiento de las partes, el Tribunal puede realizar mediación.</li><li><strong>Mediación con Carácter Racial</strong>: La mediación respeta las costumbres y hábitos de todas las razas; los ancianos raciales o representantes étnicos pueden participar en la mediación.</li><li><strong>Efecto de la Mediación</strong>: Un acuerdo de mediación legalmente efectivo tiene fuerza vinculante; el incumplimiento puede solicitarse su ejecución.</li></ul><h3 id="iv-resolucion-alternativa-de-disputas" tabindex="-1">(IV) Resolución Alternativa de Disputas <a class="header-anchor" href="#iv-resolucion-alternativa-de-disputas" aria-label="Permalink to &quot;(IV) Resolución Alternativa de Disputas&quot;">​</a></h3><p>Además del juicio, se establecen los siguientes métodos alternativos de resolución de disputas:</p><table tabindex="0"><thead><tr><th>Método</th><th>Contenido</th></tr></thead><tbody><tr><td>Arbitraje</td><td>Las disputas que han acordado arbitrar se resuelven por la institución de arbitraje; el laudo arbitral es definitivo</td></tr><tr><td>Determinación de Expertos</td><td>Las disputas profesionales pueden ser determinadas por instituciones expertas</td></tr><tr><td>Consulta Simbiótica</td><td>Las disputas entre razas u organizaciones se resuelven mediante el Mecanismo de Consulta Simbiótica</td></tr><tr><td>Mediación de Ancianos</td><td>Para disputas tradicionales de razas especiales, se puede adoptar la mediación de ancianos raciales</td></tr></tbody></table><h2 id="iv-sistema-de-litigio" tabindex="-1">IV. Sistema de Litigio <a class="header-anchor" href="#iv-sistema-de-litigio" aria-label="Permalink to &quot;IV. Sistema de Litigio&quot;">​</a></h2><h3 id="i-legitimacion-del-demandante" tabindex="-1">(I) Legitimación del Demandante <a class="header-anchor" href="#i-legitimacion-del-demandante" aria-label="Permalink to &quot;(I) Legitimación del Demandante&quot;">​</a></h3><p>Los siguientes sujetos tienen derecho a presentar demandas:</p><ul><li>Vidas naturales y sujetos organizacionales cuyos derechos e intereses legítimos hayan sido perjudicados</li><li>La Fiscalía Simbiótica puede presentar acciones de interés público por actos que dañen los intereses públicos</li><li>Las organizaciones de interés público legalmente designadas pueden presentar acciones de interés público dentro de sus ámbitos</li></ul><h3 id="ii-sistema-de-pruebas" tabindex="-1">(II) Sistema de Pruebas <a class="header-anchor" href="#ii-sistema-de-pruebas" aria-label="Permalink to &quot;(II) Sistema de Pruebas&quot;">​</a></h3><p>El sistema de pruebas del Tribunal Simbiótico incluye:</p><ol><li><strong>Tipos de Pruebas</strong>: Pruebas materiales, pruebas documentales, testimonios de testigos, declaraciones de las partes, opiniones periciales, actas de inspección, pruebas del dominio de la conciencia, etc.</li><li><strong>Carga de la Prueba</strong>: El demandante soporta la carga de la prueba de sus pretensiones; la parte que afirma un hecho favorable soporta la carga de la prueba de ese hecho.</li><li><strong>Pruebas Energéticas</strong>: Las pruebas extraídas del dominio de la conciencia y los rastros energéticos deben ser extraídas por instituciones legalmente autorizadas para garantizar la legalidad y autenticidad.</li><li><strong>Pruebas Transplanares</strong>: Las pruebas que involucran múltiples planos son mutuamente reconocidas y convertidas por el mecanismo de cooperación judicial transplanar.</li></ol><h3 id="iii-sistema-de-ejecucion" tabindex="-1">(III) Sistema de Ejecución <a class="header-anchor" href="#iii-sistema-de-ejecucion" aria-label="Permalink to &quot;(III) Sistema de Ejecución&quot;">​</a></h3><p>Las sentencias y resoluciones que toman efecto legal deben ejecutarse. Para quienes se nieguen a cumplir, el Tribunal puede tomar las siguientes medidas de ejecución:</p><ul><li>Congelación y transferencia de recursos de cultivo y propiedades</li><li>Restricciones energéticas y restricciones de cultivo</li><li>Anuncio público de conductas deshonestas</li><li>Detención y otras medidas coercitivas (en casos graves)</li></ul><h2 id="v-supervision-judicial" tabindex="-1">V. Supervisión Judicial <a class="header-anchor" href="#v-supervision-judicial" aria-label="Permalink to &quot;V. Supervisión Judicial&quot;">​</a></h2><p>Para garantizar la equidad judicial, se establecen los siguientes mecanismos de supervisión:</p><ul><li><strong>Supervisión del Comité de Supervisión del Ancla</strong>: El Comité de Supervisión del Ancla supervisa las actividades judiciales conforme a la ley, asegurando el funcionamiento legal de los órganos judiciales.</li><li><strong>Supervisión de Segunda Instancia y Revisión</strong>: El sistema de apelación y el sistema de revisión corrigen las sentencias erróneas de primera instancia.</li><li><strong>Supervisión Disciplinaria</strong>: El personal judicial que viole la disciplina está sujeto a acciones disciplinarias.</li><li><strong>Supervisión Social</strong>: El público supervisa las actividades judiciales mediante la observación de juicios, la opinión pública, etc.</li></ul><h2 id="vi-cooperacion-judicial-entre-planos" tabindex="-1">VI. Cooperación Judicial Entre Planos <a class="header-anchor" href="#vi-cooperacion-judicial-entre-planos" aria-label="Permalink to &quot;VI. Cooperación Judicial Entre Planos&quot;">​</a></h2><p>Para los casos transplanares, se establece el mecanismo de cooperación judicial:</p><ol><li>Reconocimiento mutuo de sentencias entre planos.</li><li>Asistencia transplanar en notificación y pruebas.</li><li>Cooperación judicial penal transplanar.</li><li>Asistencia transplanar en ejecución e intercambio de información sobre conductas deshonestas.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El <em>Sistema Judicial y Mecanismo de Adjudicación</em> es la última línea de defensa del orden del Estado de derecho de la Civilización Simbiótica del Ancla. Al establecer un sistema judicial de múltiples niveles, la institución de adjudicación multirracial y el mecanismo de adjudicación de casos de cultivo, garantiza la equidad y autoridad de la adjudicación, salvaguarda los derechos e intereses legítimos de todas las vidas y proporciona sólidas garantías judiciales para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>49-治理框架与权力制衡 (Marco de Gobernanza y Equilibrio de Poderes)</li><li>44-医疗保障法 (Ley de Garantía Médica)</li><li>30-锚点议事会职能与议事规则 (Funciones y Reglas de Procedimiento de la Asamblea Legislativa del Ancla)</li></ul>',43)])])}const b=a(n,[["render",d]]);export{m as __pageData,b as default};
